<script>
 import {onMount} from 'svelte';import {listBackups,listSites,createSiteBackup} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';
 let backups=[],sites=[],loading=true,busy=false,selected='';
 async function load(){const [r,s]=await Promise.all([listBackups(),listSites()]);if(r.ok)backups=r.data.backups||[];else notify(r.error||'Не удалось загрузить резервные копии','error');if(s.ok)sites=s.data.sites||[];loading=false}
 onMount(load);
 async function create(){if(!selected)return;const parts=selected.split(':');busy=true;const r=await createSiteBackup(Number(parts[0]),parts.slice(1).join(':'));busy=false;if(r.ok){notify('Резервная копия создана','success');backups=[{...r.data.backup,created_at:new Date().toISOString()},...backups]}else notify(r.error||'Не удалось создать backup','error')}
 function size(n){if(!n)return '—';const units=['B','KB','MB','GB'];let i=0,v=n;while(v>=1024&&i<3){v/=1024;i++}return v.toFixed(1)+' '+units[i]}
</script>
<div class="page-header"><div><div class="eyebrow">DATA PROTECTION</div><h1 class="page-title">Backup & Restore</h1><p class="page-desc">Локальные архивы сайтов на исходном Android-устройстве. Удаление сайта не удаляет backup.</p></div><Button on:click={load}>↻ Обновить</Button></div>
<section class="create-backup"><div><strong>Create website backup</strong><small>Архивирует файлы сайта на устройстве. Секретные файлы сайта могут попасть в архив.</small></div><div class="create-controls"><select class="input" bind:value={selected}><option value="">Выбрать сайт</option>{#each sites as item}<option value={item.device_id+':'+item.site.site_id}>{item.device_name} / {item.site.site_id}</option>{/each}</select><Button variant="primary" disabled={!selected||busy} loading={busy} on:click={create}>Create backup</Button></div></section>
{#if loading}<div class="empty">Загрузка резервных копий…</div>{:else if !backups.length}<div class="empty"><strong>Резервных копий пока нет</strong><p>Выберите сайт выше, чтобы создать первый архив.</p></div>{:else}
<div class="backup-list">{#each backups as b}<div class="backup-row"><span class="backup-icon">⤓</span><span class="backup-copy"><strong>{b.file_name}</strong><small>{b.resource_type} · {b.resource_id} · {new Date(b.created_at).toLocaleString()}</small></span><span class="size">{size(b.size_bytes)}</span><span class="status">{b.status}</span></div>{/each}</div>
{/if}
<div class="notice">Архивы хранятся локально на Android-устройстве и не удаляются вместе с сайтом. Restore в отдельную новую директорию и проверка целостности будут добавлены следующим этапом.</div>
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:#818cf8;font-weight:700;margin-bottom:7px}.create-backup{display:flex;justify-content:space-between;align-items:center;gap:13px;padding:14px;background:#101727;border:1px solid #253149;border-radius:11px;margin-bottom:13px}.create-backup>div:first-child{display:grid;gap:4px}.create-backup strong{font-size:11px}.create-backup small{font-size:9px;color:#64748b;max-width:420px;line-height:1.5}.create-controls{display:flex;gap:7px;min-width:360px}.create-controls select{min-width:0;flex:1}.backup-list{border:1px solid #253149;border-radius:11px;overflow:hidden;background:#101727}.backup-row{display:flex;align-items:center;gap:11px;padding:12px;border-bottom:1px solid #1e293b}.backup-row:last-child{border:0}.backup-icon{width:30px;height:30px;display:grid;place-items:center;background:#172136;color:#a5b4fc;border-radius:8px}.backup-copy{display:grid;gap:3px;min-width:0;flex:1}.backup-copy strong{font-size:10px}.backup-copy small,.size,.status{font-size:9px;color:#64748b}.size,.status{white-space:nowrap}.notice{margin-top:13px;padding:12px;border:1px solid #334155;border-radius:9px;background:#101727;color:#94a3b8;font-size:10px;line-height:1.6}
@media(max-width:700px){.create-backup{align-items:stretch;flex-direction:column}.create-controls{min-width:0}.backup-row{flex-wrap:wrap}}
</style>